scripts.C:
#CASE IDir { /* Inverse Clark~}{/* Clark~}
~ transformation */
#IF cq==1
 #IF IDir==1
      $alpha = SQRT_1BY2*SQRT_1BY3*(2.0*$A-$B-$C);
      $beta = SQRT_1BY2*($B-$C);
      $gamma = SQRT_1BY3*($A+$B+$C);
 #ELSE
      $A = SQRT_1BY3*(SQRT_2*$alpha + $gamma);
      $B = SQRT_1BY2*SQRT_1BY3*(-$alpha + SQRT_3*$beta + SQRT_2*$gamma);
      $C = SQRT_1BY2*SQRT_1BY3*(-$alpha - SQRT_3*$beta + SQRT_2*$gamma);
 #ENDIF
#ELSEIF cq==0
 #IF IDir==1
      $alpha = ONE_3RD*(2.0*$A-$B-$C);
      $beta = SQRT_1BY3*($B-$C);
      $gamma = ONE_3RD*($A+$B+$C);
 #ELSE
      $A = $alpha + $gamma;
      $B = 0.5*(-$alpha + SQRT_3*$beta) + $gamma;
      $C = 0.5*(-$alpha - SQRT_3*$beta) + $gamma;
 #ENDIF
#ENDIF

