#INCLUDE $(HomeDir)\CCoder\stdinc.pds
#STASH REAL oldVal($Dim)
#IF $dim==1
$O = $pscadlib_deriv($I, ($REAL)$T, &($oldVal[0]));
#ELSEIF $Dim > 1
#LOCAL INTEGER IVD1_1
for ($IVD1_1 = 0; $IVD1_1 < $Dim; $IVD1_1++) {
	$O[$IVD1_1] = $pscadlib_deriv($I[$IVD1_1], ($REAL)$T, &($oldVal));
}
#ENDIF

#INCLUDE $(HomeDir)\CCoder\stdinc.pds
#STASH STRUCT $DiffpolData data
#BEGIN
$data.enable_block  = 1;
$data.enable_limits = (int)$LIMIT;
$data.gain = ($REAL)$G;
$data.time = ($REAL)$T;
#IF RESET!=0
$data.init_output = ($REAL)$YO;
#ELSE
$data.init_output = $Zero;
#ENDIF
#IF Limit==1
$data.lower_limit = ($REAL)$Min;
$data.upper_limit = ($REAL)$Max;
#ELSE
$data.lower_limit = -1.0E20;
$data.upper_limit = 1.0E20;
#ENDIF
#ENDBEGIN
#IF RESET==1
$data.use_init_output = $R;
#ELSEIF RESET == 2
$data.use_init_output = (int)FIRSTSTEP;
#ELSE
$data.use_init_output = 0;
#ENDIF
#IF DIM==1
$data.input = $I;
$O = $pscadlib_diffpol(&($data));
#ELSEIF DIM>1
#LOCAL INTEGER IVD1_1
for ($IVD1_1 = 0; $IVD1_1 < $Dim; $IVD1_1++) {
	$data.input = $I[$IVD1_1];
	$O[$IVD1_1] = $pscadlib_diffpol(&($data));
}
#ENDIF

#INCLUDE $(HomeDir)\CCoder\stdinc.pds
#IF DPath==1
  #IF Dim == 1
if ($fabs($IN2) < $SmallValue) {
	$OUT = $IN1 * (($fabs($IN2) < 0.0) ? -$CONST($SmallValue) : $CONST($SmallValue));
}
else {
	$OUT = $IN1 / $IN2;
}
  #ELSEIF Dim > 1
#LOCAL INTEGER i
for (i = 0; i < $Dim; i++) {
	if ($fabs($IN2[i]) < $SmallValue) {
		$OUT[i] = $IN1[i] * (($fabs($IN2[i]) < 0.0) ? -$CONST($SmallValue) : $CONST($SmallValue));
	}
	else {
		$OUT[i] = $IN1[i] / $IN2[i];
	}
}
  #ENDIF
#ELSEIF DPath==2
  #IF Dim == 1
if ($cabs($IN2) < $SmallValue) {
	if ( $fabs($cimag($IN2)) > $fabs($creal($IN2))) {		
		$OUT = $CMult($IN1, ($cimag($IN2) < 0.0) ? $CConst(0.0, -$SmallValue) : $CConst(0.0, $SmallValue));
	}
	else if ($fabs($cimag($IN2)) < $fabs($creal($IN2))) {
		$OUT = $CMult($IN1, ($creal($IN2) < 0.0) ? $CConst(-$SmallValue, 0.0) : $CConst($SmallValue, 0.0));
	}
	else {
		$OUT = $CMult($CRMult($IN1, $SQRT_1BY2), ($creal($IN2) < 0.0) ? $CConst(-$SmallValue, -$SmallValue) : $CConst($SmallValue, $SmallValue));
	}
}
else {
	$OUT = $CDiv($IN1, $IN2);
}
  #ELSEIF Dim > 1
#LOCAL INTEGER i
for (i = 0; i < $Dim; i++) {
	if ($cabs($IN2[i]) < $SmallValue) {
		if ( $fabs($cimag($IN2[i])) > $fabs($creal($IN2[i]))) {
			$OUT[i] = $CMult($IN1[i], ($cimag($IN2[i]) < 0.0) ? $CConst(0.0, -$SmallValue) : $CConst(0.0, $SmallValue));
		}
		else if ($fabs($cimag($IN2[i])) < $fabs($creal($IN2[i]))) {
			$OUT[i] = $CMult($IN1[i], ($creal($IN2[i]) < 0.0) ? $CConst(-$SmallValue, 0.0) : $CConst($SmallValue, 0.0));
		}
		else {
			$OUT[i] = $CMult($CRMult($IN1[i], $SQRT_1BY2), ($creal($IN2[i]) < 0.0) ? $CConst(-$SmallValue, -$SmallValue) : $CConst($SmallValue, $SmallValue));
		}
	}
	else {
		$OUT[i] = $CDiv($IN1[i], $IN2[i]);
	}
}
  #ENDIF
#ENDIF

#INCLUDE $(HomeDir)\CCoder\stdinc.pds
#LOCAL INTEGER i
#IF $#DIM(A) != $#DIM(B)
#WARNING ERROR Dimension of both inputs should be the same.
#ENDIF
#IF $DPath != 2
for ($i = 0; $i < $#DIM(A); $i++) {
      $OUT = $OUT + ($A[$i] * $B[$i]);
}
#ELSE
for ($i = 0; $i < $#DIM(A); $i++) {
      $OUT = $OUT + $CMult($A[$i], $B[$i]);
}
#ENDIF

#INCLUDE $(HomeDir)\CCoder\stdinc.pds
#STASH STRUCT $ramp1 data
#BEGIN
#IF $X1 >= $X2
#ERROR Start of ramp should be less than saturating input.
#ENDIF
$data.X1 = ($REAL)$X1;
$data.X2 = ($REAL)$X2;
$data.Y1 = ($REAL)$Y1;
$data.Y2 = $Zero;
$data.Slope = ($Zero-($REAL)$Y1) / (($REAL)$X2-($REAL)$X1);
#ENDBEGIN
#IF Dim== 1
$O = $pscadlib_ramp_exe(&($data), $I);
#ELSEIF Dim>1
#LOCAL INTEGER IVD1_1
for ($IVD1_1 = 0; $IVD1_1 < $Dim; $IVD1_1++) {
	$O[$IVD1_1] = $pscadlib_ramp_exe(&($data), $I[$IVD1_1]);
}
#ENDIF

#INCLUDE $(HomeDir)\CCoder\stdinc.pds
#BEGIN
#IF $Dim==1
#STASH REAL oldVal
$oldVal = 0;
#ELSEIF $Dim >1
#STASH REAL oldVal[$Dim]
#LOCAL INTEGER IVD1_1
for ($IVD1_1 = 0; $IVD1_1 < $Dim; $IVD1_1++) {
	$oldVal[$IVD1_1] = $Zero;
}
#ENDIF
#ENDBEGIN
#IF Dim==1
if ($I < $oldVal) {
	$O = $TN;
}
else if ($I > $oldVal) {
	$O = $TP;
}
else {
	$O = $NT;
}
$oldVal = $I;
#ELSEIF $Dim>1
for ($IVD1_1 = 0; $IVD1_1 < $Dim; $IVD1_1++) {
	if ($I[$IVD1_1] < $oldVal[$IVD1_1]) {
		$O[$IVD1_1] = $TN;
	}
	else if ($I[$IVD1_1] > $oldVal[$IVD1_1]) {
		$O[$IVD1_1] = $TP;
	}
	else {
		$O[$IVD1_1] = $NT;
	}
	oldVal[$IVD1_1] = $I[$IVD1_1];	 
}
#ENDIF

