	}
	else if ($I[$IVD1_1] > - ($REAL)$BP) {
		$O[$IVD1_1] = ($REAL)$GL * $I[$IVD1_1];
	}
	else {
	$O[$IVD1_1] = ($REAL)$GU * $I[$IVD1_1] - $X;
	}
}
#ENDIF

