#INCLUDE $(HomeDir)\CCoder\stdinc.pds
#BEGIN
#IF $Dim == 1
#STASH INTEGER ValIn 
#STASH REAL OutPrev
#ELSE
#STASH INTEGER ValIn($Dim)	 
#STASH REAL OutPrev($Dim)	
#ENDIF
#ENDBEGIN
#IF $Dim == 1
if ((FIRSTSTEP) || ($ValIn != $IN)) {
	$ValIn = $IN;
	$OUT = $OutPrev + ($REAL)$Incr;
	if (FIRSTSTEP) {
		$OUT = ($REAL)$START;
	} 
	$OutPrev = $OUT;
}
$OUT = $OutPrev;
#ELSEIF $Dim > 1
#LOCAL INTEGER IVD1_1
for ($IVD1_1 = 0; $IVD1_1 < $Dim; $IVD1_1++) {
	if ((FIRSTSTEP) || ($ValIn[IVD1_1] != $In[IVD1_1])) {
		$ValIn[IVD1_1] = $In[IVD1_1];
		$Out[IVD1_1] = $OutPrev[IVD1_1] + ($REAL)$Incr;
		if (FIRSTSTEP) {
			$Out[IVD1_1] = ($REAL)$Start;
		}
		$OutPrev[IVD1_1] = $Out[IVD1_1];
	}
	$OUT[IVD1_1] = $OutPrev[IVD1_1];
}
#ENDIF

#IF Dim==1
$OUT = ($IN > 0) ? 1 : (($IN < 0) ? -1 : 0);
#ELSEIF Dim>1
#LOCAL INTEGER i
for (i = 0; i < $Dim; i++) {
	$OUT[i] = ($IN[i] > 0) ? 1 : (($IN[i] < 0) ? -1 : 0);
}
#ENDIF

