      CALL E_TF3W_CFG($#[2],$Ideal,RVD1_1,$f,$Xl12,$Xl13,$Xl23,$CuL,RVD1_2,RVD1_3,RVD1_4,$Im1)
      CALL E_TF3W_CFG($#[3],$Ideal,RVD1_1,$f,$Xl12,$Xl13,$Xl23,$CuL,RVD1_2,RVD1_3,RVD1_4,$Im1)
      IF ($NLL .LT. 1.0E-6) THEN
        RVD1_5 = 0.0
        IVD1_1 = 0
      ELSE
        RVD1_8 = $NLL
        RVD1_5 = 9.0/($Tmva*RVD1_8)
        IVD1_1 = 1
      ENDIF
      RVD1_6 = RVD1_5*RVD1_2*RVD1_2
      RVD1_7 = RVD1_5*RVD1_3*RVD1_3
