#BEGIN
 #LOCAL INTEGER IVD1_1
 #LOCAL REAL RVD1_1
 #LOCAL REAL RVD1_2
 #LOCAL REAL RVD1_3
 #LOCAL REAL RVD1_4
 #LOCAL REAL RVD1_5
 #LOCAL REAL RVD1_6
 #LOCAL REAL RVD1_7
 #LOCAL REAL RVD1_8
 #LOCAL REAL RVD1_9
 #LOCAL REAL RVD1_10
      CALL COMPONENT_ID(ICALL_NO,$#Component)
      RVD1_1 = ONE_3RD*$Tmva
      RVD1_2 = $V1~
 #CASE YD1 {~*SQRT_1BY3} {~}
      RVD1_3 = $V2~
 #CASE YD2 {~*SQRT_1BY3} {~}
      RVD1_4 = $V3~
 #CASE YD3 {~*SQRT_1BY3} {~}
      RVD1_5 = $V4~
 #CASE YD4 {~*SQRT_1BY3} {~}
      CALL E_TF4W3_CFG($#[1],$Ideal,RVD1_1,$f,$Xl12,$Xl13,$Xl14,$Xl23,$Xl24,$Xl34,$CuL1,$CuL2,$CuL3,$CuL4,RVD1_2,RVD1_3,RVD1_4,RVD1_5,$Im1)
      CALL E_TF4W3_CFG($#[2],$Ideal,RVD1_1,$f,$Xl12,$Xl13,$Xl14,$Xl23,$Xl24,$Xl34,$CuL1,$CuL2,$CuL3,$CuL4,RVD1_2,RVD1_3,RVD1_4,RVD1_5,$Im1)
      CALL E_TF4W3_CFG($#[3],$Ideal,RVD1_1,$f,$Xl12,$Xl13,$Xl14,$Xl23,$Xl24,$Xl34,$CuL1,$CuL2,$CuL3,$CuL4,RVD1_2,RVD1_3,RVD1_4,RVD1_5,$Im1)
      IF ($NLL .LT. 1.0E-6) THEN
        RVD1_6 = 0.0
        IVD1_1 = 0
      ELSE
        RVD1_9 = $NLL
        RVD1_6 = 12.0/($Tmva*RVD1_9)
        IVD1_1 = 1
      ENDIF
